const promise = new Promise((resolve) => {
  chrome.storage.local.get(['user'], resolve);
});

let isDone = false;

const setup = async () => {
  try {
    const $html = document.querySelector('html');
    $html.dataset.extensionId = chrome.runtime.id;
    const { user } = await promise;
    const { installationDate, settings, engine, userId } = user;
    $html.dataset.installationDate = installationDate;
    $html.dataset.engine = engine || (settings || {}).engine || 'oh';
    $html.dataset.userId = userId;

    isDone = true;
    // eslint-disable-next-line no-empty
  } catch (err) {}
};

setup();

document.addEventListener('readystatechange', () => {
  if (document.readyState !== 'interactive') return;
  if (!isDone) setup();
});
